Q: Pure virtual function issue A: <p>Here's another approach to solving the problem of overloading virtual methods that have a different amount of arguments. This will work provided that the <code>parameter-types</code> are of the same type. If the types differ, then you may have to apply <code>templates</code> and use <code>template-type deduction</code> or use <code>variadic function templates</code>...</p>
<p>Here is the example code and the generated assembly compiled with <code>GCC 10.2</code> which can be seen on <a href="https://godbolt.org/z/55c4nd" rel="nofollow noreferrer">Compiler Explorer</a>.</p>
<p><em>CPP</em></p>
<pre><code>class Base {
public:
    virtual void foo(int a, int b, int c, int d) = 0;
};

class Bar : public Base {
public:
    // Requires All 4 Argumements - Don't Deafult any Parameter
    virtual void foo(int a, int b, int c, int d) override {
        // Use every parameter for this version of the function
    }
};

class Baz : public Base {
public:
    // Requires 3 Arguments - Default the Last Parameter
    virtual void foo(int a, int b, int c, int d = 0) override {
        // Use the first three parameters within this version of the function. 
    }
};

class Fiz : public Base {
public:
    // Requires 2 Arguments - Default the Last 2 Parameters
    virtual void foo(int a, int b = 0, int c = 0, int d = 0) override {
        // Use the first two parameters within this version of the function.   
    }
};

class Buz : public Base {
public:
    // Requires Only 1 Agument - Default All but the 1st Parameter
    virtual void foo(int a, int b = 0, int c = 0, int d = 0) override {
        // Use only the first parameter within this version of the function.
    }
};


int main() {
    Bar bar;
    bar.foo(1,2,3,4);
    Baz baz;
    baz.foo(5,6,7);
    Fiz fiz;
    fiz.foo(8,9);
    Buz buz;
    buz.foo(10);

    return 0;
} 
</code></pre>
